#include <stdio.h>
#define SIZE 5

typedef struct {
    int items[SIZE];
    int front, rear;
} Queue;

void init(Queue *q) {
    q->front = -1;
    q->rear = -1;
}

int isEmpty(Queue *q) {
    return q->front == -1;
}

void enq(Queue *q, int value) {
    if (q->front == -1) q->front = 0;
    q->items[++(q->rear)] = value;
}

int deq(Queue *q) {
    int item = q->items[q->front];
    q->front++;
    if (q->front > q->rear) init(q);
    return item;
}

int main( ) {
    Queue q;
    init(&q);
    enq(&q, 10);
    enq(&q, 20);
    enq(&q, 30);
    printf("%d 그리고 %d", deq(&q), deq(&q));
    return 0;
}

